// Shipment API endpoints
app.MapGet("api/shipments", async (ApplicationDbContext db) =>
{
    var shipments = await db.Shipments
        .OrderByDescending(s => s.CreatedAt)
        .Select(s => new ShipmentTracker.Client.Models.Shipment
        {
            Id = s.Id,
            TrackingNumber = s.TrackingNumber,
            Status = s.Status,
            Origin = s.Origin,
            Destination = s.Destination,
            EstimatedDelivery = s.EstimatedDelivery,
            CustomerEmail = s.CustomerEmail,
            CreatedAt = s.CreatedAt
        })
        .ToListAsync();
    return Results.Ok(shipments);
}).RequireAuthorization("DispatcherPolicy");

app.MapGet("api/shipments/track/{trackingNumber}", async (string trackingNumber, ApplicationDbContext db) =>
{
    var entity = await db.Shipments
        .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
    if (entity is null) return Results.NotFound();
    return Results.Ok(new ShipmentTracker.Client.Models.Shipment
    {
        Id = entity.Id,
        TrackingNumber = entity.TrackingNumber,
        Status = entity.Status,
        Origin = entity.Origin,
        Destination = entity.Destination,
        EstimatedDelivery = entity.EstimatedDelivery,
        CustomerEmail = entity.CustomerEmail,
        CreatedAt = entity.CreatedAt
    });
}).RequireAuthorization();

app.MapPut("api/shipments/{id}/status", async (int id, StatusUpdateRequest request, ApplicationDbContext db) =>
{
    var entity = await db.Shipments.FindAsync(id);
    if (entity is null) return Results.NotFound();
    entity.Status = request.Status;
    await db.SaveChangesAsync();
    return Results.Ok();
}).RequireAuthorization("DispatcherPolicy");

app.Run();

