using Microsoft.AspNetCore.Identity;
using Microsoft.EntityFrameworkCore;

namespace ShipmentTracker.Data;

public static class SeedData
{
    public static async Task InitializeAsync(IServiceProvider serviceProvider)
    {
        using var scope = serviceProvider.CreateScope();
        var db = scope.ServiceProvider.GetRequiredService<ApplicationDbContext>();

        await db.Database.MigrateAsync();

        var roleManager = scope.ServiceProvider.GetRequiredService<RoleManager<IdentityRole>>();
        string[] roles = ["Dispatcher", "Customer"];
        foreach (var role in roles)
        {
            if (!await roleManager.RoleExistsAsync(role))
                await roleManager.CreateAsync(new IdentityRole(role));
        }

        if (!await db.Shipments.AnyAsync())
        {
            db.Shipments.AddRange(
                new ShipmentEntity
                {
                    TrackingNumber = "TRK-001-2026",
                    Status = "In Transit",
                    Origin = "New York, USA",
                    Destination = "London, UK",
                    EstimatedDelivery = DateTime.UtcNow.AddDays(3),
                    CustomerEmail = "customer@example.com",
                    CreatedAt = DateTime.UtcNow.AddDays(-2)
                },
                new ShipmentEntity
                {
                    TrackingNumber = "TRK-002-2026",
                    Status = "Pending",
                    Origin = "Tokyo, Japan",
                    Destination = "Sydney, Australia",
                    EstimatedDelivery = DateTime.UtcNow.AddDays(5),
                    CustomerEmail = "buyer@example.com",
                    CreatedAt = DateTime.UtcNow.AddDays(-1)
                },
                new ShipmentEntity
                {
                    TrackingNumber = "TRK-003-2026",
                    Status = "Delivered",
                    Origin = "Berlin, Germany",
                    Destination = "Paris, France",
                    EstimatedDelivery = DateTime.UtcNow.AddDays(-1),
                    CustomerEmail = "client@example.com",
                    CreatedAt = DateTime.UtcNow.AddDays(-5)
                },
                new ShipmentEntity
                {
                    TrackingNumber = "TRK-004-2026",
                    Status = "Delayed",
                    Origin = "Shanghai, China",
                    Destination = "Los Angeles, USA",
                    EstimatedDelivery = DateTime.UtcNow.AddDays(7),
                    CustomerEmail = "customer@example.com",
                    CreatedAt = DateTime.UtcNow.AddDays(-3)
                },
                new ShipmentEntity
                {
                    TrackingNumber = "TRK-005-2026",
                    Status = "In Transit",
                    Origin = "Mumbai, India",
                    Destination = "Dubai, UAE",
                    EstimatedDelivery = DateTime.UtcNow.AddDays(2),
                    CustomerEmail = "buyer@example.com",
                    CreatedAt = DateTime.UtcNow.AddDays(-1)
                }
            );
            await db.SaveChangesAsync();
        }
    }
}

